static boolean isPalindrome(String s) {
    String x = s.toLowerCase(Locale.ROOT);
    for (int i=0,j=x.length()-1; i<j; i++,j--) if (x.charAt(i)!=x.charAt(j)) return false;
    return true;
}

static boolean isPrime(int n) {
    if (n < 2) return false;
    if (n % 2 == 0) return n == 2;
    for (int i=3; i<=n/i; i+=2) if (n%i==0) return false;
    return true;
}

static List<Integer> primesUpTo(int n) {
    boolean[] composite = new boolean[Math.max(0,n+1)];
    for (int p=2; p<=n/p; p++) if (!composite[p])
        for (int j=p*p; j<=n; j+=p) composite[j]=true;
    List<Integer> out=new ArrayList<>();
    for(int i=2;i<=n;i++) if(!composite[i]) out.add(i);
    return out;
}

static BigInteger factorial(int n) {
    if(n<0) throw new IllegalArgumentException("n must be >= 0");
    BigInteger r=BigInteger.ONE;
    for(int i=2;i<=n;i++) r=r.multiply(BigInteger.valueOf(i));
    return r;
}

static List<Long> fibonacci(int count) {
    List<Long> out=new ArrayList<>(); long a=0,b=1;
    for(int i=0;i<count;i++){out.add(a); long next=a+b; a=b; b=next;}
    return out;
}

static boolean isArmstrong(int n) {
    if(n<0) return false; String s=Integer.toString(n); int p=s.length(); long sum=0;
    for(char c:s.toCharArray()) sum+=(long)Math.pow(c-'0',p);
    return sum==n;
}

static boolean isNumberPalindrome(int n) {
    if(n<0) return false; int original=n; long rev=0;
    while(n>0){rev=rev*10+n%10; n/=10;} return rev==original;
}

static int sumDigits(int n) {
    long v=Math.abs((long)n); int sum=0;
    while(v>0){sum+=(int)(v%10);v/=10;} return sum;
}

static int countDigits(int n) {
    long v=Math.abs((long)n); int count=1;
    while(v>=10){v/=10;count++;} return count;
}

static int reverseInt(int n) {
    long r=0; while(n!=0){r=r*10+n%10;n/=10;}
    if(r<Integer.MIN_VALUE||r>Integer.MAX_VALUE) throw new ArithmeticException("overflow");
    return (int)r;
}

static Set<Character> duplicateChars(String s){
    Set<Character> seen=new HashSet<>(), dup=new LinkedHashSet<>();
    for(char c:s.toCharArray()) if(!seen.add(c)) dup.add(c); return dup;
}

static Optional<Character> firstUnique(String s){
    Map<Character,Integer> m=new LinkedHashMap<>(); for(char c:s.toCharArray()) m.merge(c,1,Integer::sum);
    return m.entrySet().stream().filter(e->e.getValue()==1).map(Map.Entry::getKey).findFirst();
}

static Optional<Character> firstRepeating(String s){
    Set<Character> seen=new HashSet<>(); for(char c:s.toCharArray()) if(!seen.add(c)) return Optional.of(c);
    return Optional.empty();
}

static Map<Character,Long> charFrequency(String s){
    Map<Character,Long> m=new LinkedHashMap<>(); for(char c:s.toCharArray()) m.merge(c,1L,Long::sum); return m;
}

static boolean areAnagrams(String a,String b){
    char[] x=a.replaceAll("\\s+","").toLowerCase(Locale.ROOT).toCharArray();
    char[] y=b.replaceAll("\\s+","").toLowerCase(Locale.ROOT).toCharArray();
    if(x.length!=y.length)return false; Arrays.sort(x);Arrays.sort(y);return Arrays.equals(x,y);
}

static String removeDuplicateChars(String s){
    StringBuilder out=new StringBuilder(); Set<Character> seen=new LinkedHashSet<>();
    for(char c:s.toCharArray()) if(seen.add(c)) out.append(c); return out.toString();
}

static int[] countVowelsConsonants(String s){
    int v=0,c=0; for(char ch:s.toLowerCase(Locale.ROOT).toCharArray()) if(ch>='a'&&ch<='z'){if("aeiou".indexOf(ch)>=0)v++;else c++;}
    return new int[]{v,c};
}

static String reverseEachWord(String s){
    return Arrays.stream(s.split(" ",-1)).map(w->new StringBuilder(w).reverse().toString()).collect(Collectors.joining(" "));
}

static String reverseWordOrder(String s){
    String t=s.trim(); if(t.isEmpty())return ""; List<String> words=new ArrayList<>(Arrays.asList(t.split("\\s+")));
    Collections.reverse(words); return String.join(" ",words);
}

static Optional<String> longestWord(String s){
    return Arrays.stream(s.split("\\s+")).filter(w->!w.isEmpty()).max(Comparator.comparingInt(String::length));
}

static int longestUniqueLength(String s){
    Map<Character,Integer> last=new HashMap<>(); int start=0,best=0;
    for(int i=0;i<s.length();i++){char c=s.charAt(i); if(last.containsKey(c))start=Math.max(start,last.get(c)+1); last.put(c,i); best=Math.max(best,i-start+1);} return best;
}

static Optional<Character> mostFrequent(String s){
    Map<Character,Integer> m=new LinkedHashMap<>(); for(char c:s.toCharArray())m.merge(c,1,Integer::sum);
    return m.entrySet().stream().max(Map.Entry.comparingByValue()).map(Map.Entry::getKey);
}

static Set<String> duplicateWords(String s){
    Map<String,Integer> m=new LinkedHashMap<>(); for(String w:s.toLowerCase(Locale.ROOT).split("[^\\p{L}\\p{N}]+")) if(!w.isEmpty())m.merge(w,1,Integer::sum);
    return m.entrySet().stream().filter(e->e.getValue()>1).map(Map.Entry::getKey).collect(Collectors.toCollection(LinkedHashSet::new));
}

static String compress(String s){
    StringBuilder out=new StringBuilder(); for(int i=0;i<s.length();){char c=s.charAt(i);int j=i;while(j<s.length()&&s.charAt(j)==c)j++;out.append(c).append(j-i);i=j;} return out.toString();
}

static String longestPalindrome(String s){
    if(s.isEmpty())return ""; int start=0,best=1;
    for(int i=0;i<s.length();i++){int a=expand(s,i,i),b=expand(s,i,i+1),len=Math.max(a,b);if(len>best){best=len;start=i-(len-1)/2;}}
    return s.substring(start,start+best);
}
static int expand(String s,int l,int r){while(l>=0&&r<s.length()&&s.charAt(l)==s.charAt(r)){l--;r++;}return r-l-1;}

static <K,V extends Comparable<? super V>> Map<K,V> sortByValue(Map<K,V> input){
    return input.entrySet().stream().sorted(Map.Entry.comparingByValue()).collect(Collectors.toMap(Map.Entry::getKey,Map.Entry::getValue,(a,b)->a,LinkedHashMap::new));
}

class LruCache<K,V> extends LinkedHashMap<K,V>{
    private final int capacity;
    LruCache(int capacity){super(16,0.75f,true);if(capacity<1)throw new IllegalArgumentException();this.capacity=capacity;}
    @Override protected boolean removeEldestEntry(Map.Entry<K,V> eldest){return size()>capacity;}
}

class QueueWithStacks<T>{
    private final Deque<T> in=new ArrayDeque<>(),out=new ArrayDeque<>();
    void offer(T value){in.push(value);}
    T poll(){moveIfNeeded();return out.poll();}
    T peek(){moveIfNeeded();return out.peek();}
    boolean isEmpty(){return in.isEmpty()&&out.isEmpty();}
    private void moveIfNeeded(){if(out.isEmpty())while(!in.isEmpty())out.push(in.pop());}
}
